# al dueño cómo salió cada pick. La marca settled_notified_at (migración 008
# de tnode-bet) evita repetir; `--only-new` devuelve y marca en un solo paso.
_BET_SETTLED_JOB = "tnode-bet-settled"
_BET_SETTLED_EVERY_MIN = 60
_BET_SETTLED_MESSAGE = (
    "Revisa si se cerró algún pick. Corre PRIMERO la liquidación (ignora su "
